import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function TeacherActivities({ timetable, teachingSubject, userName }) {
  const [activeSubTab, setActiveSubTab] = useState('forum'); 

  // --- 💬 1. Class Forum Discussion Stream ---
  const [messages, setMessages] = useState([
    { id: 1, sender: `${userName || 'Teacher'}`, text: 'Hello class, please resolve any questions regarding the first chapter here.', isMe: true },
    { id: 2, sender: 'Student Node', text: 'Thank you teacher, the active lesson resources are perfectly clear.', isMe: false }
  ]);
  const [typeText, setTypeText] = useState('');

  const handleSend = (e) => {
    e.preventDefault();
    if (!typeText.trim()) return;
    const newMsg = { id: Date.now(), sender: `${userName || 'Teacher'}`, text: typeText, isMe: true };
    setMessages([...messages, newMsg]);
    setTypeText('');
  };

  // --- 🧩 2. Layered Lesson Activities Schema ---
  const [activityTopics, setActivityTopics] = useState([]); 
  const [selectedTopicId, setSelectedTopicId] = useState(''); 
  const [topicTitle, setTopicTitle] = useState(''); 
  const [formGrade, setFormGrade] = useState('Grade 8');

  const [centralBankPool, setCentralBankPool] = useState([]); 
  const [activePaperQuestions, setActivePaperQuestions] = useState([]); 
  const [bankFilterGrade, setBankFilterGrade] = useState('Grade 8');
  const [selectedBankIds, setSelectedBankIds] = useState([]);

  const targetSubject = teachingSubject || 'Mathematics';

  const refreshData = () => {
    // Read centralized bank questions
    axios.get('http://localhost:8082/api/get-bank')
      .then(res => setCentralBankPool(Array.isArray(res.data) ? res.data : []))
      .catch(err => console.error(err));

    // Load active activities generated dynamically
    axios.get('http://localhost:8082/api/lesson-activities')
      .then(res => {
        const allData = Array.isArray(res.data) ? res.data : [];
        // Extract unique lesson names hosted by this instructor
        const uniqueLessons = [];
        const seen = new Set();
        allData.forEach(item => {
          if (item.teacher_name === userName && !seen.has(item.lesson_name)) {
            seen.add(item.lesson_name);
            uniqueLessons.push({ id: item.lesson_name, title: item.lesson_name, grade: item.grade || 'Grade 8' });
          }
        });
        setActivityTopics(uniqueLessons);
      })
      .catch(err => console.error(err));

    // Load questions deployed under specific lesson modules
    if (selectedTopicId) {
      axios.get('http://localhost:8082/api/lesson-activities')
        .then(res => {
          const allData = Array.isArray(res.data) ? res.data : [];
          setActivePaperQuestions(allData.filter(q => q.lesson_name === selectedTopicId));
        })
        .catch(err => console.error(err));
    } else {
      setActivePaperQuestions([]);
    }
  };

  useEffect(() => {
    refreshData();
  }, [activeSubTab, selectedTopicId]);

  // Step 1: Initialize New Activity Workspace Node
  const handleCreateTopic = (e) => {
    e.preventDefault();
    alert(`Success: Activity placeholder "${topicTitle}" initialized. You can now link bank instances below.`);
    setSelectedTopicId(topicTitle);
    setTopicTitle('');
  };

  // Step 3: Bulk link checked question modules to database
  const handleBulkLinkToTopic = () => {
    if (!selectedTopicId || selectedBankIds.length === 0) return;
    const questionsToLink = filteredBankQuestions.filter(q => selectedBankIds.includes(q.id));

    const promises = questionsToLink.map(bq => {
      return axios.post('http://localhost:8082/api/lesson-activities', {
        lesson_name: selectedTopicId,
        question_type: bq.option_a ? 'MCQ' : 'BLANK',
        question_text: bq.question_text,
        option_a: bq.option_a,
        option_b: bq.option_b,
        option_c: bq.option_c,
        option_d: bq.option_d,
        correct_answer: bq.correct_option || bq.correct_answer,
        subject: targetSubject,
        teacher_name: userName
      });
    });

    Promise.all(promises).then(() => {
      alert("Success: Selection committed to database framework!");
      setSelectedBankIds([]);
      refreshData();
    });
  };

  const handleUnlinkQuestion = (id) => {
    if (window.confirm("Remove this question item from the module?")) {
      axios.delete(`http://localhost:8082/api/lesson-activities/${id}`).then(() => refreshData());
    }
  };

  const filteredBankQuestions = centralBankPool.filter(q => 
    String(q.grade).toLowerCase() === bankFilterGrade.toLowerCase() &&
    String(q.subject || q.subject_name).toLowerCase().includes(targetSubject.toLowerCase())
  );

  const isAllSelected = filteredBankQuestions.length > 0 && filteredBankQuestions.every(q => selectedBankIds.includes(q.id));
  const handleToggleSelectAll = () => { setSelectedBankIds(isAllSelected ? [] : filteredBankQuestions.map(q => q.id)); };
  const handleToggleSelectQuestion = (id) => { setSelectedBankIds(selectedBankIds.includes(id) ? selectedBankIds.filter(i => i !== id) : [...selectedBankIds, id]); };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '20px', fontFamily: 'sans-serif' }}>
      <div style={styles.tabContainer}>
        <button onClick={() => setActiveSubTab('forum')} style={styles.tabButton(activeSubTab === 'forum', '#145c2e')}>💬 Class Chat Forum</button>
        <button onClick={() => setActiveSubTab('activities')} style={styles.tabButton(activeSubTab === 'activities', '#6b21a8')}>🧩 Lesson Activities Creator</button>
      </div>

      {activeSubTab === 'forum' && (
        <div style={styles.workspaceCard}>
          <h3 style={styles.cardSectionTitle}>Active Stream Feed ({targetSubject})</h3>
          <div style={styles.chatScroller}>
            {messages.map(m => (
              <div key={m.id} style={{ alignSelf: m.isMe ? 'flex-start' : 'flex-end', backgroundColor: m.isMe ? '#e2e8f0' : '#dcfce7', padding: '12px 18px', borderRadius: '12px', maxWidth: '70%', fontSize: '13.5px', display: 'flex', flexDirection: 'column' }}>
                <strong style={{ fontSize: '11px', color: m.isMe ? '#475569' : '#15803d', marginBottom: '4px' }}>{m.sender}</strong>
                <span>{m.text}</span>
              </div>
            ))}
          </div>
          <form onSubmit={handleSend} style={{ display: 'flex', gap: '12px', marginTop: '20px' }}>
            <input type="text" placeholder="Type message or broad broadcast context..." value={typeText} onChange={e => setTypeText(e.target.value)} style={styles.chatInput} />
            <button type="submit" style={styles.broadcastBtn}>Broadcast 🚀</button>
          </form>
        </div>
      )}

      {activeSubTab === 'activities' && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
            <div style={styles.interactiveCard('#15803d')}>
              <h4 style={styles.stepTitle('#15803d')}>Step 1: Define Activity Topic Label</h4>
              <form onSubmit={handleCreateTopic} style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                <input type="text" placeholder="e.g., Lesson 01 - Practice Exercise" value={topicTitle} onChange={e => setTopicTitle(e.target.value)} required style={styles.premiumInput} />
                <select value={formGrade} onChange={e => setFormGrade(e.target.value)} style={styles.premiumInput}>
                  <option value="Grade 6">Grade 6</option><option value="Grade 7">Grade 7</option><option value="Grade 8">Grade 8</option><option value="Grade 9">Grade 9</option>
                </select>
                <button type="submit" style={styles.actionSubmitBtn('#15803d')}>Initialize Topic Scope</button>
              </form>
            </div>

            <div style={styles.interactiveCard('#2563eb')}>
              <h4 style={styles.stepTitle('#2563eb')}>Step 2: Active Target Module Selector</h4>
              <select value={selectedTopicId} onChange={e => setSelectedTopicId(e.target.value)} style={{ ...styles.premiumInput, marginTop: '20px' }}>
                <option value="">-- Select Deployment Target Module --</option>
                {activityTopics.map((t, idx) => (
                  <option key={idx} value={t.id}>{t.title}</option>
                ))}
              </select>
            </div>
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: '1.1fr 1.2fr', gap: '25px', alignItems: 'start' }}>
            <div style={styles.interactiveCard('#6b21a8')}>
              <h3 style={styles.formTitle}>📚 Centralized Question Repository Pool</h3>
              <select value={bankFilterGrade} onChange={e => setBankFilterGrade(e.target.value)} style={{ ...styles.premiumInput, marginBottom: '15px' }}>
                <option value="Grade 6">Grade 6</option><option value="Grade 7">Grade 7</option><option value="Grade 8">Grade 8</option><option value="Grade 9">Grade 9</option>
              </select>

              <div style={styles.bulkHeader}>
                <label style={styles.bulkLabel}>
                  <input type="checkbox" checked={isAllSelected} onChange={handleToggleSelectAll} /> Select All Pool ({filteredBankQuestions.length})
                </label>
                <button onClick={handleBulkLinkToTopic} disabled={selectedBankIds.length === 0 || !selectedTopicId} style={{ ...styles.bulkBtn, backgroundColor: (selectedBankIds.length === 0 || !selectedTopicId) ? '#cbd5e1' : '#6b21a8' }}>Deploy Selected ({selectedBankIds.length})</button>
              </div>

              <div style={styles.listScroller}>
                {filteredBankQuestions.map((q, idx) => (
                  <div key={q.id || idx} style={styles.bankItemRow}>
                    <input type="checkbox" disabled={!selectedTopicId} checked={selectedBankIds.includes(q.id)} onChange={() => handleToggleSelectQuestion(q.id)} style={{ transform: 'scale(1.1)', marginTop: '4px' }} />
                    <div style={{ flex: 1 }}>
                      <span style={styles.typeBadge(q.option_a ? 'MCQ' : 'BLANK')}>{q.option_a ? 'MCQ Standard' : 'Short Field'}</span>
                      <p style={styles.itemQuestionText}>{q.question_text}</p>
                      {q.option_a && <div style={styles.itemMcqGrid}><div>A) {q.option_a}</div><div>B) {q.option_b}</div></div>}
                      <span style={{ fontSize: '12px', color: '#16a34a', fontWeight: 'bold' }}>Answer Key Target: {q.correct_option || q.correct_answer}</span>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            <div style={styles.blueprintCard}>
              <h3 style={{ margin: '0 0 15px 0', fontSize: '15px', borderBottom: '2px solid #e2e8f0', paddingBottom: '8px', fontWeight: 'bold' }}>📋 Active Student Deployment Blueprint</h3>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                {activePaperQuestions.map((q, idx) => (
                  <div key={q.id || idx} style={styles.blueprintItem}>
                    <div style={{ display: 'flex', gap: '10px', alignItems: 'flex-start' }}>
                      <span style={{ fontWeight: 'bold', fontSize: '13.5px' }}>({idx + 1})</span>
                      <div style={{ flex: 1 }}>
                        <p style={{ margin: 0, fontSize: '13.5px', fontWeight: '600' }}>{q.question_text}</p>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '8px' }}>
                          <span style={{ fontSize: '12px', color: '#16a34a', fontWeight: 'bold' }}>Key: {q.correct_answer}</span>
                          <button type="button" onClick={() => handleUnlinkQuestion(q.id)} style={styles.unlinkMiniBtn}>✕ Remove</button>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
                {activePaperQuestions.length === 0 && <p style={styles.emptyText}>No question nodes linked to the target dashboard blueprint.</p>}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

const styles = {
  tabContainer: { display: 'flex', gap: '5px', backgroundColor: '#f1f5f9', padding: '6px', borderRadius: '12px', width: 'fit-content' },
  tabButton: (isActive, color) => ({ padding: '10px 22px', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', fontSize: '13px', backgroundColor: isActive ? color : 'transparent', color: isActive ? 'white' : '#64748b' }),
  workspaceCard: { backgroundColor: 'white', padding: '25px', borderRadius: '16px', border: '1px solid #e2e8f0', display: 'flex', flexDirection: 'column' },
  cardSectionTitle: { margin: 0, fontSize: '15px', fontWeight: 'bold' },
  chatScroller: { border: '1px solid #e2e8f0', borderRadius: '12px', height: '280px', backgroundColor: '#f8fafc', padding: '20px', overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: '15px', marginTop: '15px' },
  chatInput: { flex: 1, padding: '12px 16px', borderRadius: '8px', border: '1px solid #cbd5e1', fontSize: '13.5px', outline: 'none' },
  broadcastBtn: { backgroundColor: '#145c2e', color: 'white', border: 'none', padding: '0 25px', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer' },
  interactiveCard: (color) => ({ backgroundColor: 'white', padding: '22px', borderRadius: '15px', borderTop: `5px solid ${color}`, borderLeft: '1px solid #e2e8f0', borderRight: '1px solid #e2e8f0', borderBottom: '1px solid #e2e8f0' }),
  stepTitle: (color) => ({ margin: 0, color: color, fontWeight: 'bold', fontSize: '14px' }),
  formTitle: { margin: '0 0 10px 0', fontSize: '15px', fontWeight: 'bold' },
  premiumInput: { width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', fontSize: '13.5px', boxSizing: 'border-box', outline: 'none' },
  actionSubmitBtn: (color) => ({ color: 'white', backgroundColor: color, border: 'none', padding: '11px', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', marginTop: '10px', width: '100%' }),
  bulkHeader: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', backgroundColor: '#f1f5f9', padding: '10px 15px', borderRadius: '10px', marginBottom: '12px', border: '1px solid #cbd5e1' },
  bulkLabel: { fontSize: '12.5px', fontWeight: 'bold', display: 'flex', alignItems: 'center', gap: '6px' },
  bulkBtn: { color: 'white', border: 'none', padding: '6px 14px', borderRadius: '6px', fontSize: '12px', fontWeight: 'bold', cursor: 'pointer' },
  listScroller: { display: 'flex', flexDirection: 'column', gap: '12px', maxHeight: '350px', overflowY: 'auto' },
  bankItemRow: { display: 'flex', gap: '12px', padding: '14px', backgroundColor: '#f8fafc', borderRadius: '12px', border: '1px solid #e2e8f0', alignItems: 'flex-start' },
  typeBadge: (type) => ({ fontSize: '10px', fontWeight: 'bold', padding: '2px 6px', borderRadius: '4px', backgroundColor: type === 'MCQ' ? '#dbeafe' : '#f3e8ff', color: type === 'MCQ' ? '#2563eb' : '#6b21a8' }),
  itemQuestionText: { margin: '6px 0', fontSize: '13.5px', fontWeight: '600' },
  itemMcqGrid: { display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '4px', fontSize: '12px', color: '#64748b' },
  blueprintCard: { backgroundColor: 'white', padding: '25px', borderRadius: '16px', border: '1px solid #cbd5e1', minHeight: '200px' },
  blueprintItem: { borderBottom: '1px dashed #e2e8f0', paddingBottom: '12px', marginBottom: '4px' },
  unlinkMiniBtn: { border: 'none', background: 'none', color: '#ef4444', fontSize: '11.5px', fontWeight: 'bold', cursor: 'pointer' },
  emptyText: { color: '#94a3b8', fontStyle: 'italic', fontSize: '12.5px', textAlign: 'center', padding: '30px' }
};
